    ('倐', '숙', '倏(前條)의 俗字.', '2026-11-25T00:32:24.834844Z'::timestamptz),
    ('𠉦', '숙', '夙(夕部 三畫〈p.481〉)의 古字.', '2026-11-25T00:32:24.834844Z'::timestamptz),
